@mixin responsive-typography($font: $primary-font, $size: $base-font-size, $line-height: $base-line-height) {
  @include typography($font, $size, $line-height);

  @media (min-width: 768px) {
    font-size: $size * 1.2;
    line-height: $line-height * 1.2;
  }

  @media (min-width: 1024px) {
    font-size: $size * 1.4;
    line-height: $line-height * 1.4;
  }
}

