/**
 * Converts a string to uppercase without using built-in string manipulation functions.
 * @param {string} input - The input string to be converted.
 * @returns {string} The uppercase version of the input string.
 */
function toUpperCase(input) {
    // Handle empty input
    if (!input || input.length === 0) {
        return '';
    }

    // Create a lookup table for ASCII uppercase conversion
    const asciiLookup = {
        'a': 'A', 'b': 'B', 'c': 'C', 'd': 'D', 'e': 'E', 'f': 'F',
        'g': 'G', 'h': 'H', 'i': 'I', 'j': 'J', 'k': 'K', 'l': 'L',
        'm': 'M', 'n': 'N', 'o': 'O', 'p': 'P', 'q': 'Q', 'r': 'R',
        's': 'S', 't': 'T', 'u': 'U', 'v': 'V', 'w': 'W', 'x': 'X',
        'y': 'Y', 'z': 'Z'
    };

    // Convert each character to uppercase using the lookup table
    let result = '';
    for (let i = 0; i < input.length; i++) {
        const char = input[i];
        // Check if the character is a lowercase letter
        if (char >= 'a' && char <= 'z') {
            // Use the lookup table to get the uppercase version
            result += asciiLookup[char];
        } else {
            // If not a lowercase letter, leave it unchanged
            result += char;
        }
    }

    return result;
}

